import sys

def lcs(X, Y):
    m = len(X)
    n = len(Y)
    L = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                L[i][j] = 0
            elif X[i - 1] == Y[j - 1]:
                L[i][j] = L[i - 1][j - 1] + 1
            else:
                L[i][j] = max(L[i - 1][j], L[i][j - 1])
    return L[m][n]

def reconstruct_lcs(X, Y, L):
    index = L[len(X)][len(Y)]
    lcs = [""] * (index + 1)
    lcs[index] = ""
    i = len(X)
    j = len(Y)
    while i > 0 and j > 0:
        if X[i - 1] == Y[j - 1]:
            lcs[index - 1] = X[i - 1]
            i -= 1
            j -= 1
            index -= 1
        elif L[i - 1][j] > L[i][j - 1]:
            i -= 1
        else:
            j -= 1
    return "".join(lcs)

def shortest_supersequence(s, t):
    common = reconstruct_lcs(s, t, lcs(s, t))
    result = []
    i, j, k = 0, 0, 0
    while k < len(common):
        while i < len(s) and s[i] != common[k]:
            result.append(s[i])
            i += 1
        while j < len(t) and t[j] != common[k]:
            result.append(t[j])
            j += 1
        result.append(common[k])
        i += 1
        j += 1
        k += 1
    result.append(s[i:])
    result.append(t[j:])
    open_count = 0
    final_result = []
    for char in result:
        if char == '(':
            open_count += 1
            final_result.append(char)
        elif char == ')':
            if open_count > 0:
                open_count -= 1
                final_result.append(char)
            else:
                final_result.append('(')
                final_result.append(')')
    while open_count > 0:
        final_result.append(')')
        open_count -= 1
    return "".join(final_result)

s = sys.stdin.readline().strip()
t = sys.stdin.readline().strip()
print(shortest_supersequence(s, t))
